# hypothesis: A metaclass __call__ annotated to return Widget keeps Widget(...) and build(kind: type[T]) typed as Widget, and both calls run through the metaclass counter once.
from __future__ import annotations

from typing import reveal_type


class Counted(type):
    made: int = 0

    def __call__(cls, value: int) -> Widget:
        Counted.made += 1
        return super().__call__(value)


class Widget(metaclass=Counted):
    def __new__(cls, value: int) -> Widget:
        return super().__new__(cls)

    def __init__(self, value: int) -> None:
        self.value = value


def build[T: Widget](kind: type[T], value: int) -> T:
    return kind(value)


w = Widget(3)
reveal_type(w)
b = build(Widget, 5)
reveal_type(b)
print(w.value, b.value, Counted.made)
